arguments.command:
cd /workspace && python3 submission/ipv6_replay.py plan examples/manifest.json > /workspace/tmp/dev/plan.out; echo "exit=$?"; python3 - <<'EOF'
import json
got = json.load(open('/workspace/tmp/dev/plan.out'))
exp = json.load(open('/workspace/examples/expected-plan.json'))
print("plan match:", got == exp)
